import glob, re

files = glob.glob('config/*.yaml')
configs = {}
for f in files:
    with open(f) as fh:
        configs[f] = fh.read()

uniform_keys = [
    'service.port', 'service.request_timeout_ms', 'service.max_body_kb',
    'database.pool_size', 'database.statement_timeout_ms', 'database.ssl_mode',
    'cache.ttl_s', 'cache.max_entries', 'auth.issuer', 'auth.token_ttl_s',
    'auth.allow_anonymous', 'tls.verify', 'tls.min_version', 'logging.format',
    'logging.sample_rate', 'features.new_checkout', 'features.async_refunds',
    'features.rate_limiting', 'payments.provider', 'payments.retry_limit',
    'payments.backoff_ms', 'payments.idempotency', 'database.port',
    'auth.required_scopes', 'service.name'
]

# Let's extract values using simple regex or parsing
for uk in uniform_keys:
    sec, key = uk.split('.')
    # search section and key
    vals = {}
    for f, content in configs.items():
        # find section block
        # simple approach: parse line by line
        current_sec = None
        val = None
        for line in content.splitlines():
            line_stripped = line.strip()
            if not line_stripped or line_stripped.startswith('#'):
                continue
            if not line.startswith(' ') and not line.startswith('\t') and line_stripped.endswith(':'):
                current_sec = line_stripped[:-1]
            elif current_sec == sec:
                m = re.match(r'^[\s-]*([a-zA-Z0-9_.-]+)\s*:\s*(.*)$', line_stripped)
                if m:
                    k, v = m.groups()
                    if k == key:
                        val = v.strip()
        vals[f] = val

    # Check frequency of values
    val_counts = {}
    for f, v in vals.items():
        val_counts.setdefault(v, []).append(f)
    if len(val_counts) > 1:
        print(f'=== Key {uk} varies ===')
        for v, fs in val_counts.items():
            print(f'  Value {v!r}: {fs}')
